/**
 * 读机器人的长期记忆（bots/<名字>/记忆.md）；没有时是空字符串。
 * @param bot 机器人。
 */
async readMemory(bot: RoleInfo): Promise<string> {
  return (await readOptional(path.join(bot.dir, '记忆.md'))) ?? '';
}

}


/** 一个机器人或智能体（两者字段一样，区别是机器人有记忆和自己的会话目录）。 */
export interface RoleInfo {
  /** bot 是机器人，agent 是智能体。 */
  kind: 'bot' | 'agent';

  /** 名字，就是文件夹名。 */

/** 积木。 */
const blocks: Record<string, string> = { ...role.system };
if (actor.kind === 'bot') {
  /** 机器人的长期记忆。 */
  const memory = await runtime.readMemory(role);
  if (memory.trim()) {
    blocks.记忆 = memory;
  }
}

/** 运行时目录。 */
dir: string;

/** 公共共享区：所有 bot 都能读写的记忆。 */
sharedDir: string;

/** 角色区的上级目录：每个 bot 一个子文件夹，放它的经历、对话列表和自己的记忆。 */
rolesDir: string;
